window.MLFF_MODEL = {"id":"allegro","name":"Allegro","fullName":"Allegro: Learning Local Equivariant Representations for Large-Scale Atomistic Dynamics","year":2023,"authors":"A. Musaelian, S. Batzner, A. Johansson, L. Sun, C. J. Owen, M. Kornbluth, B. Kozinsky","paper":{"title":"Learning local equivariant representations for large-scale atomistic dynamics","venue":"Nature Communications 14, 579 (2023)","url":"https://www.nature.com/articles/s41467-023-36329-y"},"repos":["allegro","nequip"],"family":"spherical-equivariant","tags":["严格局域","E(3) 等变","边上张量轨道","LAMMPS 多 GPU 空间分解","基础模型 Allegro-OAM-L"],"framework":"PyTorch + e3nn（NequIP 框架扩展包；可选 Triton / cuEquivariance 张量积内核）","license":"MIT（基础模型权重 CC-BY-4.0）","oneLiner":"严格局域的 E(3) 等变势：等变特征不放在原子上，而放在每条有向边 i→j 上；每层只让边特征与“中心原子 i 的环境嵌入”（i 的全部邻居 k 方向球谐的加权和）做一次张量积，体序逐层 +1，却从不在原子之间传消息。每条边最后读出一个能量并加到中心原子上，因此感受野恒等于 r_c，可以像经典势一样做空间分解并行。","analogy":"把每个原子想成一个只看自家周围的“观察站”，站里为每个邻居 j 配一名专员，手里拿着“i→j 这条连线”的档案。每一轮，专员只查看本站的“全景雷达图”（所有邻居方向的加权汇总），把自己的连线档案与雷达图按旋转规则（CG 系数）交叉比对，档案里就多了“我和第三、第四个邻居构成什么形状”的信息。但各站之间从不打电话——所以谁也看不到自己截断球外的世界；也正因如此，把上亿原子的体系切块分给许多 GPU 时，每块只需借来边界外一层 r_c 厚的原子坐标就能独立算完，不必每层都和邻居 GPU 通信。","arch":{"geometry":"边向量 r_ij → 长度（Bessel × 多项式包络，可按元素对设不同截断）+ 方向（实球谐 Y_l^m，l ≤ l_max）","equivariance":"E(3) 等变（球谐 + CG 张量积）；基础模型 parity=False，只保留与球谐同宇称的 irreps","lmax":"必填、无代码默认（教程 1）；Allegro-MP-L / OAM-L 均为 3","bodyOrder":"张量轨道每层 +1 体：1 层 → 3 体、2 层 → 4 体（文档），依此类推；标量 MLP 再做非线性组合","layers":"代码默认 2；Allegro-MP-L 5 层、Allegro-OAM-L 4 层（Matbench 模型卡）","cutoff":"r_max 必填（教程 5 Å）；MP-L 6 Å、OAM-L 7 Å","receptiveField":"= r_c（严格局域）：E_i 只依赖以 i 为中心、半径 r_c 球内的原子，与层数无关","message":"无原子间消息：V_ij ⊗_CG Γ_i，Γ_i = Σ_k w_ik·Y(r̂_ik)/√n̄（同通道 CG 张量积）；标量 latent MLP 生成下一层权重","readout":"各层标量 latent 拼接 → MLP → 边能 E_ij → 对中心 i 求和 ×1/(√2·√n̄) → 逐元素 scale/shift →（可选 ZBL）→ 求和","forces":"conservative","forcesDetail":"F = −∂E/∂R；复用 nequip 的 ForceStressOutput，一次 torch.autograd.grad 同时对坐标与应变求导","stress":"对称化虚拟应变同时作用于坐标与晶胞，σ = (1/V)∂E/∂ε，virial = −σV","longRange":"无；r_c 之外完全不可见，且不能靠堆层扩大","dispersion":"无内置色散，仓库内无 D3 接口；基础模型训练集 MPtrj / OMat24 / sAlex 为 PBE(+U) 级","chargeSpin":"无总电荷/自旋输入","otherOutputs":"原子能、逐边能量 E_ij（edge energy 字段）、维里/应力；无偶极、电荷、磁矩等读出头","strictlyLocal":true,"complexity":"O(N·M·T·C_t·P_TP) 边上同通道张量积 + O(N·M·T·W²) 标量 MLP；P_TP 随 l_max 快速增长（文档：CG 张量积 ∝ l_max⁶）","accel":"Triton 自定义 TP 内核（推理）、cuEquivariance（训练+推理，二者互斥）、nequip-compile（TorchScript/AOTInductor）、torch.compile、LAMMPS pair_allegro（Kokkos/MPI/多 GPU）、ASE"},"scores":{"speed":{"v":4,"why":"没有原子间消息，每层每条边只做一次同通道张量积（张量通道通常保持很少），主要容量放在便宜的标量 MLP 上，并有 Triton/cuEq 内核；但 l_max=3、宽 MLP 逐边计算，仍比描述符/线性模型慢。"},"expressiveness":{"v":4,"why":"严格等变、l_max=3、张量轨道逐层提升体序，精度接近深层消息传递模型；但信息被限制在单个截断球内，无法组合更远的环境。"},"longRange":{"v":1,"why":"严格局域，没有色散、静电或电荷模块，感受野就是 r_c。"},"scalability":{"v":5,"why":"严格局域 → LAMMPS pair_allegro 支持 MPI/Kokkos/多 GPU 空间分解，只需一层 r_c 厚的 ghost 原子，层与层之间无需通信。"},"physics":{"v":4,"why":"保守力、多项式包络在 r_c 处平滑归零、原子能求和保证广延性、张量积严格等变；ZBL 只是可选项，两个基础模型均未启用（zbl_potential: false）。"},"coverage":{"v":2,"why":"能量/力/应力/维里之外只有原子能与逐边能量，没有偶极、电荷、磁矩等额外性质头。"}},"steps":[{"stage":"input","title":"输入构型：坐标、原子类型、晶胞","plain":"输入是 N 个原子的笛卡尔坐标 R、原子类型编号、晶胞矩阵 C 与周期性标志。Allegro 的能量网络最后被 nequip 的 ForceStressOutput 包裹：调用网络前先把坐标设为可求导，并叠加一个全零的对称“虚拟应变”，后面的力和应力都由这一次准备好的自动微分得到。","math":"\\mathcal{S}=\\{(\\mathbf r_i, Z_i)\\}_{i=1}^{N},\\ \\mathbf C\\in\\mathbb R^{3\\times3},\\ \\text{pbc}\\in\\{0,1\\}^3","code":[{"repo":"nequip","file":"nequip/nn/grad_output.py","start":175,"end":191,"lang":"python","excerpt":"symmetric_displacement = 0.5 * (\n    displacement + displacement.transpose(-1, -2)\n)\ndid_pos_req_grad: bool = pos.requires_grad\npos.requires_grad_(True)\nif num_batch > 1:\n    # bmm is natom in batch\n    # batched [natom, 1, 3] @ [natom, 3, 3] -> [natom, 1, 3] -> [natom, 3]\n    data[AtomicDataDict.POSITIONS_KEY] = pos + torch.bmm(\n        pos.unsqueeze(-2),\n        torch.index_select(symmetric_displacement, 0, batch),\n    ).squeeze(-2)\nelse:\n    # (num_atoms, 3), (3, 3) -> (num_atoms, 3)\n    data[AtomicDataDict.POSITIONS_KEY] = pos + torch.sum(\n        pos.view(-1, 3, 1) * symmetric_displacement, 1\n    )","caption":"ForceStressOutput：坐标打开 requires_grad，并叠加对称化虚拟应变","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/grad_output.py#L175-L191"},{"repo":"allegro","file":"allegro/model/allegro_models.py","start":273,"end":283,"lang":"python","excerpt":"total_energy_sum = AtomwiseReduce(\n    irreps_in=prev_irreps_out,\n    reduce=\"sum\",\n    field=AtomicDataDict.PER_ATOM_ENERGY_KEY,\n    out_field=AtomicDataDict.TOTAL_ENERGY_KEY,\n)\nmodules.update({\"total_energy_sum\": total_energy_sum})\n\n# === finalize model ===\nenergy_model = SequentialGraphNetwork(modules)\nreturn ForceStressOutput(energy_model, do_derivatives)","caption":"AllegroModel 的最外层就是 ForceStressOutput","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L273-L283"}]},{"stage":"graph","title":"邻居图：r_c 内的有向边 i→j（周期像 / ghost 原子）","plain":"用 vesin / matscipy / ASE 后端找出距离小于 r_c 的全部有向原子对，记录周期平移 S；边向量在模型内由坐标可微地重算。Allegro 的所有特征都“挂”在这些有向边上：i→j 与 j→i 是两条不同的边，edge_index[0] 是中心原子 i。为 LAMMPS 编译（pair_allegro 目标）时，周期像被直接展开成 ghost 原子——严格局域保证只需要一层 r_c 厚的 ghost。","math":"\\mathcal N(i)=\\{\\,j:\\ \\lVert\\mathbf r_{ij}\\rVert<r_c\\,\\},\\qquad \\mathbf r_{ij}=\\mathbf r_j-\\mathbf r_i+\\mathbf S_{ij}\\mathbf C","code":[{"repo":"nequip","file":"nequip/data/_nl.py","start":130,"end":154,"lang":"python","excerpt":"    first_idex, second_idex, shifts = vesin_nl(\n        cutoff=float(r_max), full_list=True\n    ).compute(points=temp_pos, box=temp_cell, periodic=periodic, quantities=\"ijS\")\n    # vesin returns uint64\n    first_idex = first_idex.astype(np.int64)\n    second_idex = second_idex.astype(np.int64)\n\nelif backend == NEIGHBORLIST_BACKEND_MATSCIPY:\n    first_idex, second_idex, shifts = matscipy_nl(\n        \"ijS\",\n        pbc=pbc,\n        cell=temp_cell,\n        positions=temp_pos,\n        cutoff=float(r_max),\n    )\nelif backend == NEIGHBORLIST_BACKEND_ASE:\n    first_idex, second_idex, shifts = ase.neighborlist.primitive_neighbor_list(\n        \"ijS\",\n        pbc,\n        temp_cell,\n        temp_pos,\n        cutoff=float(r_max),\n        self_interaction=False,\n        use_scaled_positions=False,\n    )","caption":"近邻表后端：vesin / matscipy / ASE，返回 (i, j, S)","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/data/_nl.py#L130-L154"},{"repo":"nequip","file":"nequip/nn/utils.py","start":86,"end":118,"lang":"python","excerpt":"pos = data[AtomicDataDict.POSITIONS_KEY]\nedge_index = data[edge_index_field]\nedge_vec = torch.index_select(pos, 0, edge_index[1]) - torch.index_select(\n    pos, 0, edge_index[0]\n)\nif AtomicDataDict.CELL_KEY in data:\n    # ^ note that to save time we don't check that the edge_cell_shifts are trivial if no cell is provided; we just assume they are either not present or all zero.\n    # NOTE: ASE cell vectors as rows convention\n    cell = data[AtomicDataDict.CELL_KEY]\n    edge_cell_shift = data[edge_cell_shift_field]\n    if AtomicDataDict.BATCH_KEY in data:\n        # treat batched cell case\n        edge_indexed_batches = torch.index_select(\n            data[AtomicDataDict.BATCH_KEY], 0, edge_index[0]\n        )\n        # nj <- n1j <- n1j + n1i @ nij\n        edge_vec = torch.baddbmm(\n            edge_vec.view(-1, 1, 3),\n            edge_cell_shift.view(-1, 1, 3),\n            torch.index_select(cell, 0, edge_indexed_batches),\n        ).view(-1, 3)\n        # TODO: is there a more efficient way to do the above without creating an [n_edge] and [n_edge, 3, 3] tensor?\n    else:\n        # if batch key absent, we assume that cell has batch dims 1,\n        # so we can avoid creating the large intermediate cell tensor\n        # nj <- nj + ni @ ij\n        edge_vec = edge_vec + torch.sum(\n            edge_cell_shift.view(-1, 3, 1) * cell.view(3, 3), 1\n        )\ndata[edge_vec_field] = edge_vec\nif with_lengths:\n    data[edge_len_field] = edge_vec.square().sum(1, keepdim=True).sqrt()\nreturn data","caption":"with_edge_vectors_：可微地计算边向量与长度","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/utils.py#L86-L118"},{"repo":"allegro","file":"allegro/_compile.py","start":28,"end":52,"lang":"python","excerpt":"if AtomicDataDict.EDGE_CELL_SHIFT_KEY in data:\n    # if data has PBC, we convert it to the pair_allegro format with ghost atoms and not edge cell shifts\n    # == get convenience variables ==\n    pos = data[AtomicDataDict.POSITIONS_KEY]\n    edge_idx = data[AtomicDataDict.EDGE_INDEX_KEY]\n    cell_shift = data[AtomicDataDict.EDGE_CELL_SHIFT_KEY]\n    cell = data[AtomicDataDict.CELL_KEY]\n\n    # mask for neighbors that lie outside of 000 cell\n    neighbors_outside_cell = cell_shift.abs().sum(-1) != 0\n\n    # get ghost atom positions and atom types\n    edge_idx_outside_cell = edge_idx[:, neighbors_outside_cell]\n    pos_outside_cell = torch.index_select(\n        pos, 0, edge_idx_outside_cell[1]\n    ) + torch.mm(cell_shift[neighbors_outside_cell], cell.view(3, 3))\n    type_outside_cell = torch.index_select(\n        data[AtomicDataDict.ATOM_TYPE_KEY], 0, edge_idx_outside_cell[1]\n    )\n\n    # set ghost atom neighbor indices\n    edge_idx_outside_cell[1] = torch.arange(\n        pos.size(0), pos.size(0) + pos_outside_cell.size(0), device=pos.device\n    )\n    edge_idx_inside_cell = edge_idx[:, ~neighbors_outside_cell]","caption":"pair_allegro 编译目标：把周期平移展开为 ghost 原子","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/_compile.py#L28-L52"}]},{"stage":"geometry","title":"距离编码：r/r_c → Bessel 基 × 多项式包络","plain":"边长先除以截断半径归一化为 x（还可为每一对元素单独设截断 per_edge_type_cutoff），再展开为 sinc 形式的 Bessel 基（代码默认 8 个，基础模型 12 个），并乘以 DimeNet 式多项式包络（代码默认 p=6，基础模型 p=8）。包络在 x=1 处函数值和低阶导数都为零，原子进出截断球时能量和力连续，这对 MD 能量守恒和声子计算都很关键。","math":"x_{ij}=\\frac{r_{ij}}{r_c},\\qquad B_n(x)=\\frac{\\sin(n\\pi x)}{\\pi x}\\,f_{\\text{cut}}(x),\\quad f_{\\text{cut}}(x)=1-\\tfrac{(p+1)(p+2)}{2}x^{p}+p(p+2)x^{p+1}-\\tfrac{p(p+1)}{2}x^{p+2}","code":[{"repo":"nequip","file":"nequip/nn/embedding/_edge.py","start":65,"end":80,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    # == get lengths with shape (num_edges, 1) ==\n    data = with_edge_vectors_(data, with_lengths=True)\n    r = data[AtomicDataDict.EDGE_LENGTH_KEY].view(-1, 1)\n    # == get norm ==\n    rmax_recip = self._rmax_recip\n    if self._per_edge_type:\n        # use helper to get edge types\n        data = with_edge_type_(data, self.edge_type_field)\n        edge_type = data[self.edge_type_field]\n        # convert to row-major NxN matrix index with shape (num_edges,)\n        edge_type_flat = edge_type[0] * self.num_types + edge_type[1]\n        # (num_type^2,), (num_edges,) -> (num_edges, 1)\n        rmax_recip = torch.index_select(rmax_recip, 0, edge_type_flat).unsqueeze(-1)\n    data[self.norm_length_field] = r * rmax_recip\n    return data","caption":"EdgeLengthNormalizer：r/r_c（可按边类型取不同 r_c）","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/embedding/_edge.py#L65-L80"},{"repo":"nequip","file":"nequip/nn/embedding/_edge.py","start":136,"end":150,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    # == Bessel basis ==\n    x = data[self.norm_length_field]  # (num_edges, 1)\n    # (num_edges, 1), (1, num_bessel) -> (num_edges, num_bessel)\n    bessel = (torch.sinc(x * self.bessel_weights) * self.bessel_weights).to(\n        self._output_dtype\n    )\n\n    # == polynomial cutoff ==\n    cutoff = self.cutoff(x).to(self._output_dtype)\n    data[AtomicDataDict.EDGE_CUTOFF_KEY] = cutoff\n\n    # == save product ==\n    data[self.edge_invariant_field] = bessel * cutoff\n    return data","caption":"BesselEdgeLengthEncoding：sinc 形式 Bessel 基 × 截断包络","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/embedding/_edge.py#L136-L150"},{"repo":"nequip","file":"nequip/nn/embedding/cutoffs.py","start":17,"end":27,"lang":"python","excerpt":"def forward(self, x: torch.Tensor) -> torch.Tensor:\n    \"\"\"Evaluate cutoff function.\n\n    Args:\n        x (torch.Tensor): input distance\n    \"\"\"\n    out = 1.0\n    out = out - (((self.p + 1.0) * (self.p + 2.0) / 2.0) * torch.pow(x, self.p))\n    out = out + (self.p * (self.p + 2.0) * torch.pow(x, self.p + 1.0))\n    out = out - ((self.p * (self.p + 1.0) / 2) * torch.pow(x, self.p + 2.0))\n    return out * (x < 1.0)","caption":"PolynomialCutoff：p 阶多项式包络","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/embedding/cutoffs.py#L17-L27"}]},{"stage":"embedding","title":"二体标量嵌入：径向基 ⊙（中心, 邻居）元素嵌入 → MLP","plain":"每条边的 Bessel 特征经线性层投影后，与“中心原子类型嵌入 ‖ 邻居原子类型嵌入”逐元素相乘（ProductTypeEmbedding），再过一个两体 MLP（默认 1 个隐藏层、SiLU、无偏置）得到边的不变量 z_ij。中心和邻居用两张不同的嵌入表，所以 z_ij ≠ z_ji：边是有方向的。","math":"z_{ij}=\\mathrm{MLP}_{\\text{2b}}\\Big(\\big(W_B\\,\\mathbf B(r_{ij})\\big)\\odot\\big[\\mathbf e^{\\text{c}}_{Z_i}\\,\\|\\,\\mathbf e^{\\text{n}}_{Z_j}\\big]\\Big)","code":[{"repo":"allegro","file":"allegro/nn/scalarembed.py","start":60,"end":81,"lang":"python","excerpt":"bessel_encode = BesselEdgeLengthEncoding(\n    cutoff=PolynomialCutoff(polynomial_cutoff_p),\n    num_bessels=num_bessels,\n    trainable=bessel_trainable,\n    edge_invariant_field=scalar_embed_field,\n    irreps_in=irreps_in,\n)\ntype_embed = ProductTypeEmbedding(\n    type_names=type_names,\n    initial_embedding_dim=module_output_dim,\n    forward_weight_init=forward_weight_init,\n    radial_features_in_field=scalar_embed_field,\n    edge_embed_out_field=scalar_embed_field,\n    irreps_in=bessel_encode.irreps_out,\n)\n\nreturn SequentialGraphNetwork(\n    {\n        \"bessel_encode\": bessel_encode,\n        \"type_embed\": type_embed,\n    }\n)","caption":"TwoBodyBesselScalarEmbed：Bessel 编码 + 元素对嵌入","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/scalarembed.py#L60-L81"},{"repo":"allegro","file":"allegro/nn/_edgeembed.py","start":68,"end":79,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    # == embed atom types ==\n    data = with_edge_type_(data, edge_type_field=self.edge_type_field)\n    edge_types = data[self.edge_type_field]\n    type_embed = torch.cat(\n        (self.center_embed(edge_types[0]), self.neighbor_embed(edge_types[1])),\n        dim=-1,\n    )\n    # project radial basis out to type embedding dimension and multiply\n    basis = self.basis_linear(data[self.in_field])\n    data[self.out_field] = type_embed * basis\n    return data","caption":"ProductTypeEmbedding：中心/邻居嵌入拼接后与径向投影相乘","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_edgeembed.py#L68-L79"},{"repo":"allegro","file":"allegro/model/allegro_models.py","start":134,"end":164,"lang":"python","excerpt":"edge_norm = EdgeLengthNormalizer(\n    r_max=r_max,\n    type_names=type_names,\n    per_edge_type_cutoff=per_edge_type_cutoff,\n)\nradial_chemical_embed_module = instantiate(\n    radial_chemical_embed,\n    type_names=type_names,\n    module_output_dim=(\n        num_scalar_features\n        if radial_chemical_embed_dim is None\n        else radial_chemical_embed_dim\n    ),\n    forward_weight_init=forward_normalize,\n    scalar_embed_field=AtomicDataDict.EDGE_EMBEDDING_KEY,\n    irreps_in=edge_norm.irreps_out,\n)\n# ^ note that this imposes a contract with two-body scalar embedding modules\n# i.e. they must have `type_names`, `module_output_dim`, `scalar_embed_field`, `irreps_in`\n\nscalar_embed_mlp = ScalarMLP(\n    output_dim=num_scalar_features,\n    hidden_layers_depth=scalar_embed_mlp_hidden_layers_depth,\n    hidden_layers_width=scalar_embed_mlp_hidden_layers_width,\n    nonlinearity=scalar_embed_mlp_nonlinearity,\n    bias=False,\n    forward_weight_init=forward_normalize,\n    field=AtomicDataDict.EDGE_EMBEDDING_KEY,\n    out_field=AtomicDataDict.EDGE_EMBEDDING_KEY,\n    irreps_in=radial_chemical_embed_module.irreps_out,\n)","caption":"模型装配：边长归一化 → 径向-化学嵌入 → 两体 MLP","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L134-L164"}]},{"stage":"embedding","title":"二体张量嵌入：方向球谐 × 学习的逐通道权重","plain":"边方向用实球谐 Y_l^m(r̂_ij)（l ≤ l_max，宇称 (−1)^l）编码，作为整个模型唯一的“张量基”。由 z_ij 线性投影出每个张量通道 u、每个 l 的权重，乘到球谐上，得到第 0 层的边张量特征 V⁽⁰⁾_ij。parity=True 时张量轨道允许 l ≤ l_max 的全部奇偶 irreps；基础模型用 parity=False，只保留球谐本身出现的 irreps。","math":"\\mathbf V^{(0)}_{ij,u\\,lm}=w^{(0)}_{ij,u\\,l}\\,Y_l^m(\\hat{\\mathbf r}_{ij}),\\qquad w^{(0)}_{ij}=W_V\\,z_{ij},\\quad l\\le l_{\\max}","code":[{"repo":"allegro","file":"allegro/nn/tensorembed.py","start":85,"end":96,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    data = with_edge_vectors_(data, with_lengths=False)\n    # compute weights from scalar embedding\n    edge_invariants = data[self.scalar_embedding_in_field]\n    weights = self.env_embed_linear(edge_invariants)\n    # store unweighted spherical harmonics embedding as two-body tensor basis\n    edge_vec = data[AtomicDataDict.EDGE_VECTORS_KEY]\n    edge_sh = self.sh(edge_vec).to(self._output_dtype)\n    data[self.tensor_basis_out_field] = edge_sh\n    # store two-body tensor features (weighted spherical harmonics embedding)\n    data[self.tensor_embedding_out_field] = self._edge_weighter(edge_sh, weights)\n    return data","caption":"TwoBodySphericalHarmonicTensorEmbed：球谐基 + 加权张量特征","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/tensorembed.py#L85-L96"},{"repo":"allegro","file":"allegro/nn/_strided/_channels.py","start":44,"end":62,"lang":"python","excerpt":"def forward(self, edge_attr, weights):\n    if self.weight_individual_irreps:\n        # weights are [z, u, r]\n        # edge_attr are [z, i]\n        # r runs over all irreps, which is why the weights need\n        # to be indexed in order to go from [r] to [i]\n        # [zu]r @ ri -> [zu]i -> zui\n        aux = torch.mm(\n            weights.reshape(\n                weights.size(0) * self.multiplicity_out, self._num_irreps\n            ),\n            self._rtoi,\n        ).view(\n            edge_attr.size(0),\n            self.multiplicity_out,\n            self._rtoi.shape[1],\n        )\n        # zi,zui->zui\n        return edge_attr.unsqueeze(1) * aux","caption":"MakeWeightedChannels：每个通道、每个 l 一个权重","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_strided/_channels.py#L44-L62"},{"repo":"allegro","file":"allegro/model/allegro_models.py","start":72,"end":82,"lang":"python","excerpt":"irreps_edge_sh = repr(o3.Irreps.spherical_harmonics(l_max, p=-1))\n# set tensor_track_allowed_irreps\n# note that it is treated as a set, so order doesn't really matter\nif parity:\n    # we want all irreps up to lmax\n    tensor_track_allowed_irreps = o3.Irreps(\n        [(1, (this_l, p)) for this_l in range(l_max + 1) for p in (1, -1)]\n    )\nelse:\n    # we want only irreps that show up in the original SH\n    tensor_track_allowed_irreps = irreps_edge_sh","caption":"球谐 irreps 与 parity 决定张量轨道允许的 irreps","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L72-L82"}]},{"stage":"interaction","title":"Allegro 层 ①：中心原子的环境嵌入（对邻居 k 求和）","plain":"第 0 步先把 z_ij 线性投影成两部分：标量轨道的初始特征 x⁽⁰⁾_ij 和第一层的环境权重 w⁽¹⁾_ij。每一层用当前权重给每条边 i→k 的球谐加权，再 scatter 求和到中心原子 i，并乘以 1/√(平均邻居数)，得到环境嵌入 Γ_i——它是 i 周围“邻居密度”在各角动量通道上的投影。关键在于：求和只在以 i 为中心的边上进行，不读取任何其他原子的特征。","math":"\\big[x^{(0)}_{ij}\\,\\|\\,w^{(1)}_{ij}\\big]=W_0\\,z_{ij},\\qquad \\Gamma^{(L)}_{i,u\\,lm}=\\frac{1}{\\sqrt{\\bar n}}\\sum_{k\\in\\mathcal N(i)}w^{(L)}_{ik,u\\,l}\\,Y_l^m(\\hat{\\mathbf r}_{ik})","code":[{"repo":"allegro","file":"allegro/nn/_allegro.py","start":240,"end":260,"lang":"python","excerpt":"edge_center = data[AtomicDataDict.EDGE_INDEX_KEY][0]\nnum_atoms: int = AtomicDataDict.num_nodes(data)\n\n# unweighted two-body tensor basis (i.e. spherical harmonics)\ntensor_basis = data[self.tensor_basis_in_field]\n# weighted two-body tensor features\ntensor_features = data[self.tensor_features_in_field]\n# two-body scalar embedding\ntwobody_scalar_embed = data[self.scalar_in_field]\n\n# compute zeroth layer projection and slice for\n# - two-body feature\n# - the env embedding weights in the first layer\nprojection = self.first_layer_env_embed_projection(twobody_scalar_embed)\ntwobody_scalar_features = torch.narrow(\n    projection, -1, 0, self.num_scalar_features\n)\naccumulated_scalar_features = [twobody_scalar_features]\nenv_w = torch.narrow(\n    projection, -1, self.num_scalar_features, self._env_weighter.weight_numel\n)","caption":"第 0 步：线性投影切成 x⁽⁰⁾ 与第一层环境权重","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_allegro.py#L240-L260"},{"repo":"allegro","file":"allegro/nn/_allegro.py","start":263,"end":291,"lang":"python","excerpt":"for latent, tp in zip(self.latents, self.tps):\n    # === construct env weighted tensor ===\n    env_w_edges = self._env_weighter(tensor_basis, env_w)\n\n    # scatter env_w_edges to nodes and normalize\n    env_w_scatter = scatter(\n        env_w_edges,\n        edge_center,\n        dim=0,\n        dim_size=num_atoms,\n    )\n    env_w_scatter_size0 = env_w_scatter.size(0)\n    env_w_scatter_size1 = env_w_scatter.size(1)\n    env_w_scatter_size2 = env_w_scatter.size(2)\n    data[AtomicDataDict.NODE_FEATURES_KEY] = env_w_scatter.view(\n        env_w_scatter_size0,\n        env_w_scatter_size1 * env_w_scatter_size2,\n    )\n    data = self.avg_num_neighbors_norm(data)\n\n    # === TP ===\n    # second input irreps is node-scattered env features\n    irin1 = tensor_features\n    irin2 = data[AtomicDataDict.NODE_FEATURES_KEY].view(\n        env_w_scatter_size0,\n        env_w_scatter_size1,\n        env_w_scatter_size2,\n    )\n    tensor_features = tp(irin1, irin2, edge_center)","caption":"每层：加权球谐 → scatter 到中心原子 → 归一化 → 张量积","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_allegro.py#L263-L291"},{"repo":"nequip","file":"nequip/nn/norm.py","start":48,"end":68,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    features = data[self.in_field]\n    norm_size = features.size(0)\n\n    if self.norm_key in data and data[self.norm_key].size(0) == norm_size:\n        norm_factor = data[self.norm_key]\n    else:\n        # Compute norm factor for the first time\n        if self.norm_shortcut:\n            # No need to do embedding lookup in forward\n            norm_factor = self.norm_const.expand(norm_size, -1)\n        else:\n            # Embed each avg_num_neighbors value per type\n            norm_factor = torch.nn.functional.embedding(\n                data[AtomicDataDict.ATOM_TYPE_KEY][:norm_size],\n                self.norm_const,\n            )\n        data[self.norm_key] = norm_factor  # shape: (num_local_nodes, 1)\n\n    data[self.out_field] = norm_factor * features\n    return data","caption":"AvgNumNeighborsNorm：乘 1/√n̄（可按元素）","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/norm.py#L48-L68"}]},{"stage":"interaction","title":"Allegro 层 ②：张量轨道 —— 边特征 ⊗ 环境嵌入","plain":"把 Γ_i 按 edge_center 取回到每条边 i→j，与该边上一层的张量特征 V_ij 做 Clebsch–Gordan 张量积：只在同一通道 u 内相乘（不跨通道混合），每条 (l₁, l₂ → l₃) 路径、每个通道各有一个可学习权重（tp_path_channel_coupling=True）。因为 Γ_i 是对邻居 k 的求和、张量积对它是线性的，这一步等价于“把 i→j 与每个 i→k 两两组合”，每层让体序 +1。整个过程中从没有原子 j 的特征传给 i，这就是 Allegro 与 NequIP/MACE 等消息传递模型的根本区别。","math":"\\mathbf V^{(L)}_{ij,u\\,l_3m_3}=\\sum_{(l_1,l_2\\to l_3)}c^{(L)}_{u,\\,l_1l_2l_3}\\sum_{m_1m_2}C^{l_3m_3}_{l_1m_1,l_2m_2}\\,\\mathbf V^{(L-1)}_{ij,u\\,l_1m_1}\\,\\Gamma^{(L)}_{i,u\\,l_2m_2}","code":[{"repo":"allegro","file":"allegro/nn/_strided/_contract.py","start":197,"end":226,"lang":"python","excerpt":"def _contract_conv(\n    self, x1: torch.Tensor, x2: torch.Tensor, idxs: torch.Tensor\n) -> torch.Tensor:\n    # index select from scattered x2\n    x2 = torch.index_select(x2, 0, idxs)\n\n    # for shared weights, we can precontract weights and w3j so they can be frozen together\n    # this is usually advantageous for inference, since the weights would have to be\n    # multiplied in anyway at some point\n    ww3j = torch.einsum(self._weight_w3j_einstr, self.weights, self.w3j)\n\n    # now do the TP with the pre-contracted w3j\n    if self.w3j_is_ij_diagonal:\n        # zui, zui -> zui\n        outer = x1 * x2\n        if self.path_channel_coupling:\n            # zui1, uik -> zuk\n            out = torch.sum(outer.unsqueeze(-1) * ww3j, 2)\n        else:\n            # zui, ik -> zuk\n            out = torch.mm(outer.view(-1, outer.size(2)), ww3j).view(\n                outer.size(0), outer.size(1), ww3j.size(1)\n            )\n    else:\n        # zui, zuj -> zuij\n        outer = x1.unsqueeze(-1) * x2.unsqueeze(-2)\n        if self.path_channel_coupling:\n            # zuij, uijk -> zuk\n            out = torch.sum(outer.unsqueeze(-1) * ww3j, (2, 3))\n        else:","caption":"Contracter：取回中心原子的 Γ_i，与边特征做同通道 CG 收缩","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_strided/_contract.py#L197-L226"},{"repo":"allegro","file":"docs/guide/allegro_model.rst","start":13,"end":14,"lang":"plaintext","excerpt":"- ``l_max`` governs the angular resolution of the tensor features. Reasonable ``l_max`` values to try include ``1``, ``2``, and ``3``, where raising ``l_max`` may improve accuracy at the cost of speed. **NOTE** that the computational cost does not increase linearly with ``l_max``, but rather scales polynomially due to the :math:`O(\\ell_\\text{max}^6)` scaling of the Clebsch-Gordan tensor products. Raising ``l_max`` will also increase the number of tensor paths taken, and the growth of paths is also tied to the choice of ``num_layers``.\n- ``num_layers`` is the number of Allegro layers, which corresponds to the body-ordering (``num_layers=1`` corresponds to three-body tensor features, ``num_layers=2`` corresponds to four-body tensor features, and so on). A Clebsch-Gordan tensor product occurs at each Allegro layer. It is usually appropriate to use 1, 2, or 3 layers.","caption":"文档：层数即体序（1 层 3 体、2 层 4 体），TP 代价 ∝ l_max⁶","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/docs/guide/allegro_model.rst#L13-L14"},{"repo":"allegro","file":"allegro/nn/_strided/_flashallegro.py","start":773,"end":780,"lang":"python","excerpt":"def _contract_conv(self, x1, x2, idxs):\n    # runtime conditions for triggering kernel code path\n    if (x1.is_cuda or x1.is_xpu) and not self.training:\n        return torch.ops.triton.flashallegro_forward(\n            x1,\n            x2,\n            idxs,\n            self.mode,","caption":"TritonContracter：推理时换成自定义 Triton 张量积内核","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_strided/_flashallegro.py#L773-L780"}]},{"stage":"interaction","title":"Allegro 层 ③：标量轨道 —— latent MLP（DenseNet 式拼接）","plain":"从张量积结果中取出 0e 标量（旋转不变），与之前所有层的标量特征 x⁽⁰⁾…x⁽ᴸ⁻¹⁾ 拼接，送入 latent MLP（代码默认 1 个隐藏层、宽 64、SiLU、无偏置；基础模型宽 1024、深 2–3）。输出切成两段：新的标量特征 x⁽ᴸ⁾_ij，以及下一层给球谐加权的环境权重 w⁽ᴸ⁺¹⁾。两条轨道互相喂养：张量轨道提供角度/多体信息，标量轨道提供非线性和通道混合；最后一层的张量积只输出标量，不需要的高 l 路径会被剪掉。","math":"\\big[x^{(L)}_{ij}\\,\\|\\,w^{(L+1)}_{ij}\\big]=\\mathrm{MLP}^{(L)}\\Big(x^{(0)}_{ij}\\,\\|\\cdots\\|\\,x^{(L-1)}_{ij}\\,\\|\\,\\mathbf V^{(L)}_{ij,\\,0e}\\Big)","code":[{"repo":"allegro","file":"allegro/nn/_allegro.py","start":293,"end":323,"lang":"python","excerpt":"    # Extract invariants from tensor track\n    # features has shape [z][mul][k], where scalars are first\n    scalars = tensor_features[:, :, : self._n_scalar_outs[layer_index]].reshape(\n        tensor_features.shape[0],\n        tensor_features.shape[1] * self._n_scalar_outs[layer_index],\n    )\n\n    # === Compute Latents & Slice ===\n    latents = latent(torch.cat(accumulated_scalar_features + [scalars], dim=-1))\n    # slice to\n    # 1. propagated latents\n    # 2. env embed weights for next layer (but not for last layer)\n\n    # accumulate scalar features\n    accumulated_scalar_features.append(\n        torch.narrow(latents, -1, 0, self.num_scalar_features)\n    )\n    # env embed weights\n    if layer_index < self.num_layers - 1:\n        env_w = torch.narrow(\n            latents,\n            -1,\n            self.num_scalar_features,\n            self._env_weighter.weight_numel,\n        )\n\n    # == increment counter ==\n    layer_index += 1\n\n# save accumulated scalar features\ndata[self.scalar_out_field] = torch.cat(accumulated_scalar_features, dim=-1)","caption":"提取标量 → 拼接历史标量 → latent MLP → 切出新特征与下一层权重","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_allegro.py#L293-L323"},{"repo":"allegro","file":"allegro/nn/_allegro.py","start":194,"end":215,"lang":"python","excerpt":"self.latents.append(\n    latent(\n        input_dim=(\n            # initial two-body scalar features +\n            # all scalar features from previous layer(s) (densenet structure)\n            self.num_scalar_features * (layer_idx + 1)\n            # scalars extracted from the this layer's TP:\n            # each layer executes a TP and then a latent, so the last entry in _n_scalar_outs corresponds to this layer's TP\n            + self.num_tensor_features * self._n_scalar_outs[-1]\n        ),\n        output_dim=(\n            # number of scalar features\n            self.num_scalar_features\n            # env weighter for next layer's TP (except in last layer)\n            + (\n                self._env_weighter.weight_numel\n                if layer_idx < self.num_layers - 1\n                else 0\n            )\n        ),\n    )\n)","caption":"latent MLP 的输入/输出维度（DenseNet 式累积）","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_allegro.py#L194-L215"},{"repo":"allegro","file":"allegro/nn/_allegro.py","start":119,"end":126,"lang":"python","excerpt":"for layer_idx in range(num_layers):\n    if layer_idx == self.num_layers - 1:\n        # ^ means we're doing the last layer\n        # No more TPs follow this, so only need scalars\n        ir_out = Irreps([(1, (0, 1))])\n    else:\n        # allow everything allowed\n        ir_out = self.tensor_track_allowed_irreps","caption":"最后一层张量积只输出标量 0e","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/_allegro.py#L119-L126"}]},{"stage":"readout","title":"边能量读出：每条有向边一个标量能量","plain":"Allegro 层结束后，把所有层的标量特征拼接（num_scalar_features × (层数+1) 维），送入读出 MLP（代码默认 1 个隐藏层、宽 32、SiLU、无偏置），每条有向边 i→j 输出一个能量 E_ij。读出只用不变量，所以能量严格旋转/平移不变。","math":"E_{ij}=\\mathrm{MLP}_{\\text{out}}\\big(x^{(0)}_{ij}\\,\\|\\,x^{(1)}_{ij}\\,\\|\\cdots\\|\\,x^{(T)}_{ij}\\big)\\in\\mathbb R","code":[{"repo":"allegro","file":"allegro/model/allegro_models.py","start":212,"end":230,"lang":"python","excerpt":"# === allegro readout ===\nedge_readout = ScalarMLP(\n    output_dim=1,\n    hidden_layers_depth=readout_mlp_hidden_layers_depth,\n    hidden_layers_width=readout_mlp_hidden_layers_width,\n    nonlinearity=readout_mlp_nonlinearity,\n    bias=False,\n    forward_weight_init=forward_normalize,\n    field=AtomicDataDict.EDGE_FEATURES_KEY,\n    out_field=AtomicDataDict.EDGE_ENERGY_KEY,\n    irreps_in=allegro.irreps_out,\n)\nedge_eng_sum = EdgewiseReduce(\n    field=AtomicDataDict.EDGE_ENERGY_KEY,\n    out_field=AtomicDataDict.PER_ATOM_ENERGY_KEY,\n    avg_num_neighbors=avg_num_neighbors,\n    type_names=type_names,\n    irreps_in=edge_readout.irreps_out,\n)","caption":"边能读出 MLP + EdgewiseReduce","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L212-L230"}]},{"stage":"energy","title":"边能 → 原子能 → 总能","plain":"EdgewiseReduce 把所有以 i 为中心的边能量 scatter 求和到原子 i，再乘 1/√(平均邻居数) 并除以 √2（代码注释：对 r_ij 与 r_ji 的导数都会贡献到同一原子的力）。随后按元素做 E_i ← s_Z·E_i + μ_Z（μ 通常取孤立原子参考能），可选叠加 ZBL 近核排斥（教程配置带 ZBL，两个基础模型均关闭），最后对原子求和。“边能之和 = 原子能、原子能之和 = 总能”保证了广延性与严格局域。","math":"E_i=\\mu_{Z_i}+s_{Z_i}\\,\\frac{1}{\\sqrt2\\,\\sqrt{\\bar n}}\\sum_{j\\in\\mathcal N(i)}E_{ij},\\qquad E=\\sum_{i}E_i\\ \\big(+E_{\\text{ZBL}}\\big)","code":[{"repo":"allegro","file":"allegro/nn/edgewise.py","start":42,"end":63,"lang":"python","excerpt":"def forward(self, data: AtomicDataDict.Type) -> AtomicDataDict.Type:\n    # get destination nodes 🚂\n    edge_dst = data[AtomicDataDict.EDGE_INDEX_KEY][0]\n    edge_data = data[self.field]\n\n    # === scatter ===\n    out = scatter(\n        edge_data,\n        edge_dst,\n        dim=0,\n        dim_size=AtomicDataDict.num_nodes(data),\n        reduce=self.reduce,\n    )\n    # === scale ===\n    data[AtomicDataDict.NODE_FEATURES_KEY] = out\n    data = self.norm_module(data)\n    out = data[AtomicDataDict.NODE_FEATURES_KEY] / sqrt(2)\n    # ^ factor of 2 to normalize dE/dr_i which includes both contributions from dE/dr_ij\n    # and every other derivative against r_ji.\n\n    data[self.out_field] = out\n    return data","caption":"EdgewiseReduce：边能 → 中心原子能","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/edgewise.py#L42-L63"},{"repo":"nequip","file":"nequip/nn/atomwise.py","start":243,"end":274,"lang":"python","excerpt":"# === set up ===\nin_field = data[self.field]\ntypes = data[AtomicDataDict.ATOM_TYPE_KEY].view(-1)\n# to account for local-ghost truncation in ML-IAP\ntypes = types[: in_field.size(0)]\n\nif self.has_scales:\n    if self.scales_shortcut:\n        scales = self.scales\n    else:\n        scales = torch.nn.functional.embedding(types, self.scales)\nelse:\n    scales = self.scales  # dummy for torchscript\n\nif self.has_shifts:\n    if self.shifts_shortcut:\n        shifts = self.shifts\n    else:\n        shifts = torch.nn.functional.embedding(types, self.shifts)\nelse:\n    shifts = self.shifts  # dummy for torchscript\n\n# === explicit cast ===\nin_field = in_field.to(self.out_dtype)\n\n# === scale/shift ===\nif self.has_scales and self.has_shifts:\n    # we can used an FMA for performance\n    # addcmul computes\n    # input + tensor1 * tensor2 elementwise\n    # it will promote to widest dtype, which comes from shifts/scales\n    in_field = torch.addcmul(shifts, scales, in_field)","caption":"PerTypeScaleShift：逐元素 scale/shift","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/atomwise.py#L243-L274"},{"repo":"allegro","file":"allegro/model/allegro_models.py","start":254,"end":279,"lang":"python","excerpt":"if pair_potential is not None:\n    # case where model doesn't have edge cutoffs up to this point, but pair potential required\n    if AtomicDataDict.EDGE_CUTOFF_KEY not in prev_irreps_out:\n        cutoff = AddRadialCutoffToData(\n            cutoff=PolynomialCutoff(6),\n            irreps_in=prev_irreps_out,\n        )\n        prev_irreps_out = cutoff.irreps_out\n        modules.update({\"cutoff\": cutoff})\n\n    pair_potential = instantiate(\n        pair_potential,\n        type_names=type_names,\n        irreps_in=prev_irreps_out,\n    )\n    prev_irreps_out = pair_potential.irreps_out\n    modules.update({\"pair_potential\": pair_potential})\n\n# === sum to total energy ===\ntotal_energy_sum = AtomwiseReduce(\n    irreps_in=prev_irreps_out,\n    reduce=\"sum\",\n    field=AtomicDataDict.PER_ATOM_ENERGY_KEY,\n    out_field=AtomicDataDict.TOTAL_ENERGY_KEY,\n)\nmodules.update({\"total_energy_sum\": total_energy_sum})","caption":"可选 pair potential（ZBL）→ 原子能求和","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L254-L279"}]},{"stage":"forces","title":"力：自动微分 + 严格局域带来的并行优势","plain":"力由一次 torch.autograd.grad 得到（F = −∂E/∂R），严格保守。由于 E_i 只依赖 i 的截断球，原子 k 受到的力只来自距它 r_c 以内各原子的 E_i。这正是空间分解的理想情形：LAMMPS 的 pair_allegro 让每个 MPI rank / GPU 只持有本区域原子加一层 r_c 厚的 ghost 原子，一次前向 + 反向即可算出本区能量和力的贡献，层与层之间不需要像消息传递模型那样交换 ghost 特征。代价是：r_c 之外的任何信息都永远进不来。","math":"\\mathbf F_k=-\\frac{\\partial E}{\\partial\\mathbf r_k}=-\\sum_{i:\\ i=k\\ \\text{or}\\ r_{ik}<r_c}\\frac{\\partial E_i}{\\partial\\mathbf r_k}","code":[{"repo":"nequip","file":"nequip/nn/grad_output.py","start":214,"end":229,"lang":"python","excerpt":"# Call model and get gradients\ndata = self.func(data)\n\ngrads = torch.autograd.grad(\n    [data[AtomicDataDict.TOTAL_ENERGY_KEY].sum()],\n    [pos, data[\"_displacement\"]],\n    create_graph=self.training,  # needed to allow gradients of this output during training\n)\n\n# Put negative sign on forces\nforces = grads[0]\nif forces is None:\n    # condition needed to unwrap optional for torchscript\n    assert False, \"failed to compute forces autograd\"\nforces = torch.neg(forces)\ndata[AtomicDataDict.FORCE_KEY] = forces","caption":"ForceStressOutput：autograd 求力","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/grad_output.py#L214-L229"},{"repo":"allegro","file":"README.md","start":45,"end":47,"lang":"plaintext","excerpt":"## LAMMPS Integration\n\nWe offer a LAMMPS plugin [`pair_allegro`](https://github.com/mir-group/pair_nequip_allegro) to use Allegro models in LAMMPS simulations, including support for Kokkos acceleration, MPI, and parallel multi-GPU simulations.","caption":"pair_allegro：Kokkos、MPI 与多 GPU 并行","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/README.md#L45-L47"},{"repo":"allegro","file":"docs/guide/lammps.md","start":23,"end":25,"lang":"plaintext","excerpt":"## LAMMPS Pair Style\n\nThe [`pair_nequip_allegro`](https://github.com/mir-group/pair_nequip_allegro) is an interface to use NequIP framework interatomic potentials in LAMMPS, which contains `pair_allegro` that is meant to be used for the strictly local Allegro model, which supports parallel execution and MPI in LAMMPS.","caption":"文档：严格局域的 Allegro 支持 LAMMPS 并行/MPI","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/docs/guide/lammps.md#L23-L25"}]},{"stage":"stress","title":"应力：对对称化虚拟应变求导","plain":"构造全零 3×3 位移张量并对称化（去掉对应无穷小转动的反对称部分），同时作用于坐标与晶胞；能量对它的梯度即维里，除以晶胞体积 |det C| 得到应力，并按惯例存 virial = −σV。与力共用同一次反传，零体积（非周期）帧的应力置为 NaN。","math":"\\mathbf r_i\\to\\mathbf r_i(\\mathbf 1+\\boldsymbol\\varepsilon),\\ \\mathbf C\\to\\mathbf C(\\mathbf 1+\\boldsymbol\\varepsilon),\\qquad \\boldsymbol\\sigma=\\frac{1}{V}\\frac{\\partial E}{\\partial\\boldsymbol\\varepsilon}\\Big|_{\\varepsilon=0},\\quad \\mathbf W=-V\\boldsymbol\\sigma","code":[{"repo":"nequip","file":"nequip/nn/grad_output.py","start":150,"end":177,"lang":"python","excerpt":"if num_batch > 1:\n    displacement = torch.zeros(\n        (num_batch, 3, 3),\n        dtype=pos.dtype,\n        device=pos.device,\n    )\nelse:\n    displacement = torch.zeros(\n        (3, 3),\n        dtype=pos.dtype,\n        device=pos.device,\n    )\ndisplacement.requires_grad_(True)\ndata[\"_displacement\"] = displacement\n# in the above paper, the infinitesimal distortion is *symmetric*\n# so we symmetrize the displacement before applying it to\n# the positions/cell\n# This is not strictly necessary (reasoning thanks to Mario):\n# the displacement's asymmetric 1o term corresponds to an\n# infinitesimal rotation, which should not affect the final\n# output (invariance).\n# That said, due to numerical error, this will never be\n# exactly true. So, we symmetrize the deformation to\n# take advantage of this understanding and not rely on\n# the invariance here:\nsymmetric_displacement = 0.5 * (\n    displacement + displacement.transpose(-1, -2)\n)","caption":"构造并对称化虚拟应变","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/grad_output.py#L150-L177"},{"repo":"nequip","file":"nequip/nn/grad_output.py","start":236,"end":268,"lang":"python","excerpt":"virial = virial.view(num_batch, 3, 3)\n\n# we only compute the stress (1/V * virial) if we have a cell whose volume we can compute\nif has_cell:\n    # ^ can only scale by cell volume if we have one...:\n    # Rescale stress tensor\n    # See https://github.com/atomistic-machine-learning/schnetpack/blob/master/src/schnetpack/atomistic/output_modules.py#L180\n    # See also https://en.wikipedia.org/wiki/Triple_product\n    # See also https://gitlab.com/ase/ase/-/blob/master/ase/cell.py,\n    #          which uses np.abs(np.linalg.det(cell))\n    # First dim is batch, second is vec, third is xyz\n    # Note the .abs(), since volume should always be positive\n    # det is equal to a dot (b cross c)\n    volume = torch.linalg.det(cell).abs().view(num_batch, 1, 1)\n\n    # NOTE: to support batching periodic and non-periodic structures together,\n    # frames with a zero-volume cell get NaN stress, which is meant to be handled\n    # with `ignore_nan` in loss and metrics (as for NaN stress labels).\n    # the denominator must never be zero, even for those frames since\n    # `torch.compile` feeds every unused output a materialized zero tangent,\n    # so a `1/0` local derivative would give `0 * inf = NaN` in the joint\n    # backward and poison every parameter gradient\n    has_volume = volume > 0\n    safe_volume = torch.where(has_volume, volume, torch.ones_like(volume))\n    stress = torch.where(\n        has_volume,\n        virial / safe_volume,\n        torch.full_like(virial, float(\"nan\")),\n    )\n    data[AtomicDataDict.CELL_KEY] = orig_cell\nelse:\n    stress = self._empty  # torchscript\ndata[AtomicDataDict.STRESS_KEY] = stress","caption":"维里 / 体积 → 应力","url":"https://github.com/mir-group/nequip/blob/27d9d2182da918ab7be0017d8300e53278f5e00e/nequip/nn/grad_output.py#L236-L268"}]}],"hyper":[{"name":"r_max","value":"MP-L 6.0 Å / OAM-L 7.0 Å；代码无默认（教程 5.0 Å）","note":"截断半径 = 感受野","code":{"repo":"matbench-discovery","file":"models/allegro/allegro-oam-l-0.1.yml","start":75,"end":77,"lang":"yaml","excerpt":"architecture:\n  graph_construction_radius: 7.0\n  n_layers: 4","caption":"","url":"https://github.com/janosh/matbench-discovery/blob/c70947f7fd176b8914b72c4ec9a974adfa3b4d50/models/allegro/allegro-oam-l-0.1.yml#L75-L77"}},{"name":"num_layers","value":"代码默认 2；MP-L 5、OAM-L 4","note":"Allegro 层数（每层体序 +1）","code":{"repo":"allegro","file":"allegro/model/allegro_models.py","start":106,"end":113,"lang":"python","excerpt":"# allegro layers\nnum_layers: int = 2,\nnum_scalar_features: int = 64,\nnum_tensor_features: int = 16,\nallegro_mlp_hidden_layers_depth: int = 1,\nallegro_mlp_hidden_layers_width: int = 64,\nallegro_mlp_nonlinearity: Optional[str] = \"silu\",\ntp_path_channel_coupling: bool = True,","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L106-L113"}},{"name":"l_max","value":"3（MP-L / OAM-L）；教程 1","note":"球谐与张量轨道最高阶","code":{"repo":"matbench-discovery","file":"models/allegro/allegro-mp-l-0.1.yml","start":83,"end":93,"lang":"yaml","excerpt":"upstream_config:\n  weight_decay: 1e-3\n  sph_harmonics_l_max: 3\n  n_features: 96\n  parity: false\n  zbl_potential: false\n  allegro_mlp_depth: 3\n  allegro_mlp_width: 1024\n  tensor_path_channel_coupling: true\n  polynomial_cutoff: 8\n  n_radial_bessel_basis: 12","caption":"","url":"https://github.com/janosh/matbench-discovery/blob/c70947f7fd176b8914b72c4ec9a974adfa3b4d50/models/allegro/allegro-mp-l-0.1.yml#L83-L93"}},{"name":"num_scalar_features / num_tensor_features","value":"代码默认 64 / 16（教程 64 / 32）；模型卡 n_features：MP-L 96、OAM-L 64","note":"标量轨道与张量轨道通道数；文档建议张量通道保持小","code":{"repo":"allegro","file":"allegro/model/allegro_models.py","start":106,"end":113,"lang":"python","excerpt":"# allegro layers\nnum_layers: int = 2,\nnum_scalar_features: int = 64,\nnum_tensor_features: int = 16,\nallegro_mlp_hidden_layers_depth: int = 1,\nallegro_mlp_hidden_layers_width: int = 64,\nallegro_mlp_nonlinearity: Optional[str] = \"silu\",\ntp_path_channel_coupling: bool = True,","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L106-L113"}},{"name":"allegro MLP","value":"代码默认 depth 1 × width 64（SiLU，无偏置）；MP-L depth 3、OAM-L depth 2，width 1024","note":"每层 latent MLP","code":{"repo":"matbench-discovery","file":"models/allegro/allegro-oam-l-0.1.yml","start":83,"end":93,"lang":"yaml","excerpt":"upstream_config:\n  weight_decay: 1e-8\n  sph_harmonics_l_max: 3\n  n_features: 64\n  parity: false\n  zbl_potential: false\n  allegro_mlp_depth: 2\n  allegro_mlp_width: 1024\n  tensor_path_channel_coupling: true\n  polynomial_cutoff: 8\n  n_radial_bessel_basis: 12","caption":"","url":"https://github.com/janosh/matbench-discovery/blob/c70947f7fd176b8914b72c4ec9a974adfa3b4d50/models/allegro/allegro-oam-l-0.1.yml#L83-L93"}},{"name":"parity","value":"代码默认 True；基础模型 False","note":"False 时张量轨道只保留球谐中出现的 irreps","code":{"repo":"allegro","file":"allegro/model/allegro_models.py","start":72,"end":82,"lang":"python","excerpt":"irreps_edge_sh = repr(o3.Irreps.spherical_harmonics(l_max, p=-1))\n# set tensor_track_allowed_irreps\n# note that it is treated as a set, so order doesn't really matter\nif parity:\n    # we want all irreps up to lmax\n    tensor_track_allowed_irreps = o3.Irreps(\n        [(1, (this_l, p)) for this_l in range(l_max + 1) for p in (1, -1)]\n    )\nelse:\n    # we want only irreps that show up in the original SH\n    tensor_track_allowed_irreps = irreps_edge_sh","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L72-L82"}},{"name":"tp_path_channel_coupling","value":"True（默认；基础模型亦为 true）","note":"张量积权重按“路径 × 通道”学习","code":{"repo":"allegro","file":"allegro/model/allegro_models.py","start":106,"end":113,"lang":"python","excerpt":"# allegro layers\nnum_layers: int = 2,\nnum_scalar_features: int = 64,\nnum_tensor_features: int = 16,\nallegro_mlp_hidden_layers_depth: int = 1,\nallegro_mlp_hidden_layers_width: int = 64,\nallegro_mlp_nonlinearity: Optional[str] = \"silu\",\ntp_path_channel_coupling: bool = True,","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L106-L113"}},{"name":"num_bessels","value":"代码默认 8（不可训练）；基础模型 12","note":"Bessel 径向基个数","code":{"repo":"allegro","file":"allegro/nn/scalarembed.py","start":19,"end":24,"lang":"python","excerpt":"def TwoBodyBesselScalarEmbed(\n    type_names: Sequence[str],\n    # bessel encoding\n    num_bessels: int = 8,\n    bessel_trainable: bool = False,\n    polynomial_cutoff_p: int = 6,","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/scalarembed.py#L19-L24"}},{"name":"polynomial_cutoff_p","value":"代码默认 6；基础模型 8","note":"多项式包络阶数","code":{"repo":"allegro","file":"allegro/nn/scalarembed.py","start":19,"end":24,"lang":"python","excerpt":"def TwoBodyBesselScalarEmbed(\n    type_names: Sequence[str],\n    # bessel encoding\n    num_bessels: int = 8,\n    bessel_trainable: bool = False,\n    polynomial_cutoff_p: int = 6,","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/nn/scalarembed.py#L19-L24"}},{"name":"readout MLP","value":"depth 1 × width 32（代码默认，SiLU，无偏置）","note":"边能读出 MLP","code":{"repo":"allegro","file":"allegro/model/allegro_models.py","start":114,"end":117,"lang":"python","excerpt":"# readout\nreadout_mlp_hidden_layers_depth: int = 1,\nreadout_mlp_hidden_layers_width: int = 32,\nreadout_mlp_nonlinearity: Optional[str] = \"silu\",","caption":"","url":"https://github.com/mir-group/allegro/blob/8bd074c87645b3f0c3c0cd45c73db3fea4eb270f/allegro/model/allegro_models.py#L114-L117"}},{"name":"参数量 / ZBL","value":"MP-L 约 18.7M、OAM-L 约 9.7M；zbl_potential: false","note":"Matbench Discovery 模型卡","code":{"repo":"matbench-discovery","file":"models/allegro/allegro-mp-l-0.1.yml","start":57,"end":64,"lang":"yaml","excerpt":"training_sets: [MPtrj]\nsize: L\nmodel_params: 18700000\ntraining_cost:\n  entries:\n  - hardware: NVIDIA H100\n    count: 8\n    hours_per_device: 50.0","caption":"","url":"https://github.com/janosh/matbench-discovery/blob/c70947f7fd176b8914b72c4ec9a974adfa3b4d50/models/allegro/allegro-mp-l-0.1.yml#L57-L64"}}],"speedNotes":["FLOPs 集中在两处：每层每条边一次同通道 CG 张量积（∝ 边数 × 张量通道 × 路径数），以及每层每条边一次标量 MLP（基础模型宽 1024）。没有原子间消息，总代价随边数（即原子数）线性增长。","文档指出 CG 张量积代价约 ∝ l_max⁶，路径数还随层数增长；因此推荐保持 num_tensor_features 小、把容量放到便宜的标量通道上——“窄张量、宽标量”是 Allegro 的速度来源。","加速：Triton 自定义张量积内核（仅推理，nequip-compile --modifiers enable_TritonContracter）与 cuEquivariance Contracter（训练+推理），二者互斥；配合 TorchScript / AOTInductor 编译与 torch.compile 训练。","力与应力共用一次 autograd 反传；多 GPU MD 时层与层之间无需通信，只需常规的 ghost 原子交换，这是它比消息传递模型更易扩展的原因。","Matbench Discovery 模型卡：Allegro-MP-L 约 18.7M 参数（8×H100，每卡 50 h），Allegro-OAM-L 约 9.7M 参数（12×H100，每卡 100 h）。"],"weakNotes":["严格局域：原子 i 的能量只看 r_c（MP-L 6 Å、OAM-L 7 Å）以内的原子，而且堆再多层也不会扩大；消息传递模型至少还能通过多层间接看到更远（如 6 层 NequIP 约 36 Å），Allegro 则完全没有。","网络中没有任何 r⁻⁶ 色散或 r⁻¹ 静电项，仓库也没有 D3/D4 接口；训练集 MPtrj / OMat24 / sAlex 为 PBE(+U) 级，几乎不含 vdW → 层状材料层间结合、分子晶体、物理吸附会被低估，需在外部叠加色散校正。","没有总电荷/自旋输入，也没有电荷平衡：带电缺陷、离子液体、电化学界面、长程极化与电荷转移都是风险区。","ZBL 先验只修正极短程核间排斥（教程配置可选），与弱相互作用无关；两个基础模型都没有启用 ZBL。"],"downstreamNotes":["保守力 + 多项式平滑包络 → 力连续，可做声子与热导率：Matbench Discovery κ_SRME 为 Allegro-MP-L 0.5039、Allegro-OAM-L 0.3186。","稳定性预测与几何优化：Matbench Discovery 全测试集 F1 = 0.742（MP-L）/ 0.873（OAM-L），弛豫结构 RMSD 0.0816 / 0.0651。","大规模 MD 是 Allegro 的主场：pair_allegro 支持 Kokkos、MPI 与多 GPU（nequip 文档表格：pair_nequip 仅单 rank，pair_allegro 支持多 rank）；文档称基础模型论文测试了多节点强/弱扩展（至 1 亿原子以上）。","原生应力/维里 → NPT MD、状态方程、弹性常数；可在 ASE、LAMMPS 中使用，并可从基础模型微调。","没有偶极/极化率/磁矩读出头，红外/拉曼光谱、磁性体系需另行扩展。"],"strengths":["严格局域 → 近乎理想的空间分解，LAMMPS pair_allegro 支持 MPI/Kokkos/多 GPU","严格 E(3) 等变，张量轨道逐层提升体序，精度接近深层消息传递模型","“窄张量、宽标量”设计 + Triton / cuEquivariance 内核，速度—精度平衡好","保守力、平滑截断、可选 ZBL；与 NequIP 共享训练、编译与部署工具链","提供 Allegro-OAM-L / MP-L 基础模型（CC-BY-4.0）"],"weaknesses":["感受野锁死在 r_c，无法靠堆层看得更远","无色散、静电与电荷/自旋输入","特征存在边上，内存与计算随邻居数线性增长，高密度或大 r_c 时开销大","除 E/F/S 外几乎没有额外性质输出"],"pretrained":["Allegro-OAM-L:0.1（nequip.net；OMat24 预训练 → MPtrj + sAlex 微调，约 9.7M 参数）","Allegro-MP-L:0.1（仅 MPtrj 的 compliant 模型，约 18.7M 参数）"],"mbdKeys":["allegro-mp-l-0.1","allegro-oam-l-0.1"],"arenaKeys":[],"sources":{"allegro":{"url":"https://github.com/mir-group/allegro","commit":"8bd074c87645b3f0c3c0cd45c73db3fea4eb270f","date":"2026-05-27"},"nequip":{"url":"https://github.com/mir-group/nequip","commit":"27d9d2182da918ab7be0017d8300e53278f5e00e","date":"2026-08-30"}}};
